package com.fathom.investment; import com.fathom.common.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="investment_holdings") public class InvestmentHolding extends BaseEntity { @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Enumerated(EnumType.STRING) @Column(name="asset_type",nullable=false) private AssetType assetType; @Column(nullable=false) private String name; private String provider; private String symbol; @Column(length=3,nullable=false) private String currency="INR"; @Column(name="invested_amount",nullable=false,precision=19,scale=4) private BigDecimal investedAmount=BigDecimal.ZERO; @Column(name="current_value",nullable=false,precision=19,scale=4) private BigDecimal currentValue=BigDecimal.ZERO; @Column(name="as_of_date") private LocalDate asOfDate; @Column(nullable=false) private boolean active=true; @PrePersist void init(){if(id==null)id=UUID.randomUUID();} public UUID getId(){return id;} public UUID getUserId(){return userId;} public AssetType getAssetType(){return assetType;} public String getName(){return name;} public String getProvider(){return provider;} public String getSymbol(){return symbol;} public String getCurrency(){return currency;} public BigDecimal getInvestedAmount(){return investedAmount;} public BigDecimal getCurrentValue(){return currentValue;} public LocalDate getAsOfDate(){return asOfDate;} public boolean isActive(){return active;} public void setUserId(UUID v){userId=v;} public void setAssetType(AssetType v){assetType=v;} public void setName(String v){name=v;} public void setProvider(String v){provider=v;} public void setSymbol(String v){symbol=v;} public void setCurrency(String v){currency=v;} public void setInvestedAmount(BigDecimal v){investedAmount=v;} public void setCurrentValue(BigDecimal v){currentValue=v;} public void setAsOfDate(LocalDate v){asOfDate=v;} public void setActive(boolean v){active=v;} }
